INSERT INTO "prices" VALUES(641,407,17,NULL,'8888 W Bellfort Ave, Houston. Wed Nov 11, 10:30-11:30am with Houston Food Bank; first 250 families, arrive early, registration/token may close early. Open to all regardless of background. Future dates Nov 25, Dec 9 and 23.',0.0,1.0,0.0,'2026-11-11','2026-11-11','https://www.indiahouseinc.org/community-support/food-distribution/',1,'2026-11-06');
